<summary>One-off native probe sources and reproduction</summary>

These sources are supporting investigation artifacts, included here rather than tracked in the repository. Save the three files below in `build-contribution/shader-gap-research/` under the checkout under test. Configure a Linux GCC/Ninja build at `build-contribution/half-expansion-main-build` and build `agc_driver_half_expansion_tests` first. Run `python3 build-contribution/shader-gap-research/build_half_evidence.py` in that Linux environment to export the real emitter's SPIR-V. The exporter uses the same CMake compiler definitions, include paths and shader archive.

For the Windows GPU execution used here, install the Python binding beside the scripts:

```powershell
python -m pip install --target build-contribution/shader-gap-research/python-vulkan vulkan==1.3.275.1
python build-contribution/shader-gap-research/run_half_evidence.py --device 0 --label before
```

Repeat the build/export with #1463 applied, then run with `--label after` (asserts no mismatches) and `--label negative --negative-control` (asserts exactly the injected mismatch). Use `--device 1` for the second adapter. `--label before` records mismatches without failing so a driver that already preserves the bits can also supply a baseline. JSON results include the actual adapter identity, driver number, SPIR-V hash, category counts and all 20 packed rows.

The raw expansion matrix includes signaling encodings without treating this as an instruction-level signaling-NaN or MODE oracle. The integration fixture's SDWA cases additionally execute the half-precision ldexp/round-trip path; this standalone probe directly checks widening of the selected bytes.

`export_half_evidence.cpp`

```cpp
#include "Recompiler.hpp"
#include "IntermediateRepresentation/IrProgram.hpp"
#include "SpirvBackend/SpirvEmitterInstructions.hpp"
#include <array>
#include <fstream>
#include <iostream>
#include <string>

using namespace ShaderRecompiler;

static void Save(const std::string& name, const std::vector<std::uint32_t>& words) {
    std::ofstream out(name, std::ios::binary);
    out.write(reinterpret_cast<const char*>(words.data()), words.size() * sizeof(words[0]));
    if (!out) throw std::runtime_error("failed to save " + name);
}

static void HalfConversions(const std::string& directory) {
    IrProgram program;
    const ShaderStageInputInfo inputs{};
    SpirvEmitterState state(program, inputs);
    auto& m = state.module;
    m.EmitCapability(spv::CapabilityShader);
    m.EmitCapability(spv::CapabilitySignedZeroInfNanPreserve);
    m.EmitExtension("SPV_KHR_float_controls");
    m.AddMemoryModel(spv::AddressingModelLogical, spv::MemoryModelGLSL450);
    const auto u32 = TypeU32(state);
    const auto array = m.DecoratedType(spv::OpTypeRuntimeArray, {{spv::OpDecorate, {spv::DecorationArrayStride, 4u}}}, u32);
    const auto structure = m.Type(spv::OpTypeStruct, array);
    m.AddAnnotation(spv::OpDecorate, structure, spv::DecorationBlock);
    m.AddAnnotation(spv::OpMemberDecorate, structure, 0u, spv::DecorationOffset, 0u);
    const auto buffer = m.DefineGlobalVariable(m.Type(spv::OpTypePointer, spv::StorageClassStorageBuffer, structure), spv::StorageClassStorageBuffer);
    m.AddAnnotation(spv::OpDecorate, buffer, spv::DecorationDescriptorSet, 0u);
    m.AddAnnotation(spv::OpDecorate, buffer, spv::DecorationBinding, 0u);
    const auto gid = m.DefineGlobalVariable(m.Type(spv::OpTypePointer, spv::StorageClassInput, TypeU32Vector(state, 3u)), spv::StorageClassInput);
    m.AddAnnotation(spv::OpDecorate, gid, spv::DecorationBuiltIn, spv::BuiltInGlobalInvocationId);
    const auto main = m.AllocateId();
    const auto voidType = m.Type(spv::OpTypeVoid);
    m.EmitEntryPoint(spv::ExecutionModelGLCompute, main, "main", {gid});
    m.AddExecutionMode(main, spv::ExecutionModeLocalSize, 64u, 1u, 1u);
    m.AddExecutionMode(main, spv::ExecutionModeSignedZeroInfNanPreserve, 32u);
    m.AddFunction(spv::OpFunction, voidType, main, spv::FunctionControlMaskNone, m.Type(spv::OpTypeFunction, voidType));
    m.AddFunction(spv::OpLabel, m.AllocateId());
    const auto invocation = m.AllocateId();
    m.AddFunction(spv::OpLoad, TypeU32Vector(state, 3u), invocation, gid);
    const auto index = m.AllocateId();
    m.AddFunction(spv::OpCompositeExtract, u32, index, invocation, 0u);
    const auto offset = Binary(state, spv::OpIMul, u32, index, ConstantU32(state, 5u));
    const auto address = [&](std::uint32_t component) {
        const auto result = m.AllocateId();
        m.AddFunction(spv::OpAccessChain, m.Type(spv::OpTypePointer, spv::StorageClassStorageBuffer, u32), result, buffer,
            ConstantU32(state, 0u), Binary(state, spv::OpIAdd, u32, offset, ConstantU32(state, component)));
        return result;
    };
    const auto source = m.AllocateId();
    m.AddFunction(spv::OpLoad, u32, source, address(0u));
    for (std::uint32_t component = 0; component < 4u; ++component) {
        auto selected = source;
        if (component == 1u) selected = Binary(state, spv::OpShiftRightLogical, u32, source, ConstantU32(state, 16u));
        if (component >= 2u) {
            selected = m.AllocateId();
            m.AddFunction(spv::OpBitFieldUExtract, u32, selected, source, ConstantU32(state, (component - 2u) * 8u), ConstantU32(state, 8u));
        }
        const auto expanded = EmitF16BitsToF32(state, selected);
        const auto bits = m.AllocateId();
        m.AddFunction(spv::OpBitcast, u32, bits, expanded);
        m.AddFunction(spv::OpStore, address(component + 1u), bits);
    }
    m.AddFunction(spv::OpReturn);
    m.AddFunction(spv::OpFunctionEnd);
    Save(directory + "/half-expansion-context.spv", m.Finalize());
}


int main(int argc, char** argv) {
    try {
        if (argc != 2) throw std::runtime_error("expected artifact directory");
        HalfConversions(argv[1]);
        return 0;
    } catch (const std::exception& error) {
        std::cerr << error.what() << '\n';
        return 1;
    }
}
```

