import shlex
import subprocess

here = Path(__file__).resolve().parent
root = here.parents[1]
base = root / 'build-contribution/half-expansion-main-build'
ninja = (base / 'build.ninja').read_text()
unit = re.search(r'^build (\S+\.o): CXX_COMPILER__shader_recompiler_agc_driver_\S+ (\S+) \|\|[^\n]*\n((?:  [^\n]*\n)*)', ninja, re.M)
attributes = unit.group(3)
defines = shlex.split(re.search(r'^  DEFINES = (.+)$', attributes, re.M).group(1))
