`run_half_evidence.py`

```python
from pathlib import Path
import argparse
import hashlib
import json
import math
import struct
import sys

HERE = Path(__file__).resolve().parent
sys.path.insert(0, str(HERE / 'python-vulkan'))
import vulkan as v

# The binding copies nested C structs without retaining their pointer owners.
# Retain this short-lived tool's constructor results through device destruction.
KEEP_ALIVE = []
def retain_constructor(constructor):
    def retained(*a, **kw):
        result = constructor(*a, **kw)
        KEEP_ALIVE.append(result)
        return result
    return retained
for constructor_name in dir(v):
    constructor = getattr(v, constructor_name)
    if constructor_name.startswith('Vk') and callable(constructor):
        setattr(v, constructor_name, retain_constructor(constructor))

parser = argparse.ArgumentParser()
parser.add_argument('--device', type=int, default=0)
parser.add_argument('--label', required=True)
parser.add_argument('--negative-control', action='store_true')
args = parser.parse_args()

def words(data):
    return list(struct.unpack('<' + 'I' * (len(data) // 4), data))

app = v.VkApplicationInfo(pApplicationName='AnyPS5 half expansion evidence', apiVersion=v.VK_MAKE_VERSION(1, 1, 0))
instance = v.vkCreateInstance(v.VkInstanceCreateInfo(pApplicationInfo=app), None)
physical = v.vkEnumeratePhysicalDevices(instance)[args.device]
properties = v.vkGetPhysicalDeviceProperties(physical)
print('Device:', properties.deviceName, flush=True)
float_properties = v.ffi.new('VkPhysicalDeviceFloatControlsProperties*', v.VkPhysicalDeviceFloatControlsProperties())
v.vkGetPhysicalDeviceProperties2(physical, v.VkPhysicalDeviceProperties2(pNext=float_properties))
assert float_properties.shaderSignedZeroInfNanPreserveFloat32
family = next(i for i, p in enumerate(v.vkGetPhysicalDeviceQueueFamilyProperties(physical)) if p.queueFlags & v.VK_QUEUE_COMPUTE_BIT)
extensions = [e.extensionName for e in v.vkEnumerateDeviceExtensionProperties(physical, None)]
device = v.vkCreateDevice(physical, v.VkDeviceCreateInfo(
    pQueueCreateInfos=[v.VkDeviceQueueCreateInfo(queueFamilyIndex=family, queueCount=1, pQueuePriorities=[1.0])],
    ppEnabledExtensionNames=['VK_KHR_shader_float_controls'] if 'VK_KHR_shader_float_controls' in extensions else []), None)
queue = v.vkGetDeviceQueue(device, family, 0)
memory_properties = v.vkGetPhysicalDeviceMemoryProperties(physical)
pool = v.vkCreateCommandPool(device, v.VkCommandPoolCreateInfo(queueFamilyIndex=family), None)
command = v.vkAllocateCommandBuffers(device, v.VkCommandBufferAllocateInfo(commandPool=pool,
    level=v.VK_COMMAND_BUFFER_LEVEL_PRIMARY, commandBufferCount=1))[0]
allocated = []

def memory_type(bits, flags):
    return next(i for i in range(memory_properties.memoryTypeCount)
        if bits & (1 << i) and memory_properties.memoryTypes[i].propertyFlags & flags == flags)

def buffer(size, usage):
    handle = v.vkCreateBuffer(device, v.VkBufferCreateInfo(size=size, usage=usage, sharingMode=v.VK_SHARING_MODE_EXCLUSIVE), None)
    requirements = v.vkGetBufferMemoryRequirements(device, handle)
    memory = v.vkAllocateMemory(device, v.VkMemoryAllocateInfo(allocationSize=requirements.size,
        memoryTypeIndex=memory_type(requirements.memoryTypeBits, v.VK_MEMORY_PROPERTY_HOST_VISIBLE_BIT | v.VK_MEMORY_PROPERTY_HOST_COHERENT_BIT)), None)
    v.vkBindBufferMemory(device, handle, memory, 0)
    allocated.append((handle, memory))
    return handle, memory

def write(memory, data):
    mapped = v.vkMapMemory(device, memory, 0, len(data), 0)
    mapped[:] = data
    v.vkUnmapMemory(device, memory)

def read(memory, size):
    mapped = v.vkMapMemory(device, memory, 0, size, 0)
    result = bytes(mapped)
    v.vkUnmapMemory(device, memory)
    return result

def module(name):
    code = (HERE / name).read_bytes()
    return v.vkCreateShaderModule(device, v.VkShaderModuleCreateInfo(codeSize=len(code), pCode=code), None)

def begin():
    v.vkResetCommandPool(device, pool, 0)
    v.vkBeginCommandBuffer(command, v.VkCommandBufferBeginInfo(flags=v.VK_COMMAND_BUFFER_USAGE_ONE_TIME_SUBMIT_BIT))

def submit():
    v.vkEndCommandBuffer(command)
    fence = v.vkCreateFence(device, v.VkFenceCreateInfo(), None)
    try:
        v.vkQueueSubmit(queue, 1, [v.VkSubmitInfo(pCommandBuffers=[command])], fence)
        v.vkWaitForFences(device, 1, [fence], True, 30_000_000_000)
    finally:
        v.vkDestroyFence(device, fence, None)


fixed_inputs = [0x3c003c00, 0xc000bc00, 0x80000000, 0x00008000, 0x03ff0001,
    0x040003ff, 0x7bff0400, 0xfbff7bff, 0xfc007c00, 0x7e01fe01, 0xfe017e01,
    0x7fff7e55, 0xfffffe55, 0xfff0fff0, 0xa5a500f0, 0xdead00ff, 0x7c003555,
    0x3555fc00, 0x3c000200, 0x80018001]
inputs = list(range(65536)) + fixed_inputs
while len(inputs) % 64:
    inputs.append(0)
data = b''.join(struct.pack('<5I', x, *([0xdeadbeef]*4)) for x in inputs)

def expected_half(half):
    if (half & 0x7fff) > 0x7c00:
        return ((half & 0x8000) << 16) | 0x7f800000 | ((half & 0x3ff) << 13)
    return struct.unpack('<I', struct.pack('<f', struct.unpack('<e', struct.pack('<H', half))[0]))[0]

try:
    storage, storage_memory = buffer(len(data), v.VK_BUFFER_USAGE_STORAGE_BUFFER_BIT)
    write(storage_memory, data)
    descriptor_layout = v.vkCreateDescriptorSetLayout(device, v.VkDescriptorSetLayoutCreateInfo(pBindings=[
        v.VkDescriptorSetLayoutBinding(binding=0, descriptorType=v.VK_DESCRIPTOR_TYPE_STORAGE_BUFFER, descriptorCount=1, stageFlags=v.VK_SHADER_STAGE_COMPUTE_BIT)]), None)
    descriptor_pool = v.vkCreateDescriptorPool(device, v.VkDescriptorPoolCreateInfo(maxSets=1, pPoolSizes=[
        v.VkDescriptorPoolSize(type=v.VK_DESCRIPTOR_TYPE_STORAGE_BUFFER, descriptorCount=1)]), None)
    descriptor = v.vkAllocateDescriptorSets(device, v.VkDescriptorSetAllocateInfo(descriptorPool=descriptor_pool, pSetLayouts=[descriptor_layout]))[0]
    v.vkUpdateDescriptorSets(device, 1, [v.VkWriteDescriptorSet(dstSet=descriptor, dstBinding=0, descriptorCount=1,
        descriptorType=v.VK_DESCRIPTOR_TYPE_STORAGE_BUFFER, pBufferInfo=[v.VkDescriptorBufferInfo(buffer=storage, offset=0, range=len(data))])], 0, None)
    layout = v.vkCreatePipelineLayout(device, v.VkPipelineLayoutCreateInfo(pSetLayouts=[descriptor_layout]), None)
    shader_path = HERE / 'half-expansion-context.spv'
    shader = module(shader_path.name)
    pipeline = v.vkCreateComputePipelines(device, v.VK_NULL_HANDLE, 1, [v.VkComputePipelineCreateInfo(
        stage=v.VkPipelineShaderStageCreateInfo(stage=v.VK_SHADER_STAGE_COMPUTE_BIT, module=shader, pName='main'), layout=layout)], None)[0]
    begin()
    v.vkCmdBindPipeline(command, v.VK_PIPELINE_BIND_POINT_COMPUTE, pipeline)
    v.vkCmdBindDescriptorSets(command, v.VK_PIPELINE_BIND_POINT_COMPUTE, layout, 0, 1, [descriptor], 0, None)
    v.vkCmdDispatch(command, len(inputs)//64, 1, 1)
    v.vkCmdPipelineBarrier(command, v.VK_PIPELINE_STAGE_COMPUTE_SHADER_BIT, v.VK_PIPELINE_STAGE_HOST_BIT, 0,
        1, [v.VkMemoryBarrier(srcAccessMask=v.VK_ACCESS_SHADER_WRITE_BIT, dstAccessMask=v.VK_ACCESS_HOST_READ_BIT)], 0, None, 0, None)
    submit()
    observed = words(read(storage_memory, len(data)))
    mismatches, examples, fixed_results = 0, [], []
    categories = {'quiet_nan':0, 'signaling_nan':0, 'finite_or_infinity':0}
    for i, x in enumerate(inputs[:65536+len(fixed_inputs)]):
        selected = [x & 0xffff, x >> 16, x & 0xff, (x >> 8) & 0xff]
        expected = [expected_half(h) for h in selected]
        if args.negative_control and i == 0:
            expected[0] ^= 1
        actual = observed[i*5+1:i*5+5]
        for column, (a, e) in enumerate(zip(actual, expected)):
            if a != e:
                mismatches += 1
                h = selected[column]
                category = ('quiet_nan' if h & 0x200 else 'signaling_nan') if (h & 0x7fff) > 0x7c00 else 'finite_or_infinity'
                categories[category] += 1
                if len(examples) < 8:
                    examples.append({'input':f'{x:08x}', 'column':column, 'actual':f'{a:08x}', 'expected':f'{e:08x}'})
        if i >= 65536:
            fixed_results.append({'input':f'{x:08x}', 'actual':[f'{a:08x}' for a in actual], 'expected':[f'{e:08x}' for e in expected]})
    result = {'device':properties.deviceName, 'vendor_id':properties.vendorID, 'device_id':properties.deviceID,
        'driver_version':properties.driverVersion, 'label':args.label,
        'native_rdna2_or_ps5_execution':False, 'scope':'actual half expansion emitter with runtime SSBO input; raw-bit contract, not guest floating-point mode equivalence',
        'module_sha256':hashlib.sha256(shader_path.read_bytes()).hexdigest(), 'inputs':65536+len(fixed_inputs),
        'comparisons':4*(65536+len(fixed_inputs)), 'mismatch_count':mismatches, 'mismatch_categories':categories,
        'examples':examples, 'fixed_results':fixed_results, 'negative_control':args.negative_control}
    (HERE / f'half-evidence-{args.label}-device-{args.device}.json').write_text(json.dumps(result, indent=2)+'\n')
    print(json.dumps({k:v for k,v in result.items() if k != 'fixed_results'}, indent=2), flush=True)
    if args.negative_control:
        assert mismatches == 1 and examples[0]['input'] == '00000000', 'negative control failed'
    elif args.label != 'before':
        assert mismatches == 0, 'incorrect GPU output'
finally:
    v.vkDeviceWaitIdle(device)
    for name, destroy in [('pipeline',v.vkDestroyPipeline), ('shader',v.vkDestroyShaderModule),
        ('layout',v.vkDestroyPipelineLayout), ('descriptor_pool',v.vkDestroyDescriptorPool),
        ('descriptor_layout',v.vkDestroyDescriptorSetLayout)]:
        if name in globals():
            destroy(device, globals()[name], None)
    for handle, memory in allocated:
        v.vkDestroyBuffer(device, handle, None)
        v.vkFreeMemory(device, memory, None)
    v.vkDestroyCommandPool(device, pool, None)
    v.vkDestroyDevice(device, None)
    v.vkDestroyInstance(instance, None)
```

</details>


The expectation for finite expansion was calculated independently with Python's IEEE half unpack / float pack. Quiet NaN goldens preserve the source sign and shift the payload into the FP32 mantissa, matching #1463's contract. A useful external reference is the [published native gfx1035 interpolation result](https://github.com/boykopovar/AnyPS5/pull/697#issuecomment-6012866112), where half `fe01` survives the reported interpolation as `fe01`. That is supporting arithmetic evidence, not a direct native execution of this new conversion fixture. The [AMD SDWA failure described in #1463](https://github.com/boykopovar/AnyPS5/pull/1463) motivates the packed-byte cases.

**Limits:** the local GPUs are an NVIDIA RTX 4070 Laptop GPU and an AMD Radeon 780M (RDNA3). No new RDNA2 or PS5 execution was performed. This PR adds **zero instruction coverage percentage** and does not settle PS5 SPI interpolation or per-shader MODE semantics. It remains draft pending #1463.

